@Component("trainingEnrollment-handler")
@ProcessingGroup("trainingEnrollment-processing-group")
public class TrainingEnrollmentEventHandler {
	
	// core constructor
	TrainingEnrollmentEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateTrainingEnrollmentEvent
     */
    @EventHandler
    public void handle( CreateTrainingEnrollmentEvent event) {
        entityManager.persist(new TrainingEnrollment(event.getTrainingEnrollmentId(), event.getEnrollmentNumber(), event.getCompletionDate(), event.getScore(), event.getCourse(), event.getEmployee(), event.getInstructor(), event.getStatus()));
    }

    /*
     * @param	event UpdateTrainingEnrollmentEvent
     */
    @EventHandler
    public TrainingEnrollment handle( UpdateTrainingEnrollmentEvent event) {
    	entityManager.merge(new TrainingEnrollment(event.getTrainingEnrollmentId(), event.getEnrollmentNumber(), event.getCompletionDate(), event.getScore(), event.getCourse(), event.getEmployee(), event.getInstructor(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteTrainingEnrollmentEvent
     */
    @EventHandler
    public void on( DeleteTrainingEnrollmentEvent event) {
    	TrainingEnrollment entity = new TrainingEnrollment();
   
    	// ------------------------------------------
    	// apply the TrainingEnrollmentId
    	// ------------------------------------------
    	entity.setTrainingEnrollmentId( event.getTrainingEnrollmentId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final TrainingEnrollmentRepository trainingEnrollmentEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(TrainingEnrollmentEventHandler.class.getName());

}
